#include <bits/stdc++.h>
using namespace std;

const int MAXN = 300;
const int ROOM = -1;
const int REAC = -2;
const int BAD = -3;
const int CAPSULE = ROOM;

int grid[MAXN][MAXN], capsuleCount[MAXN][MAXN];
int poisonGrid[61][MAXN][MAXN];
int mx[4] = {-1, 0, 1, 0};
int my[4] = {0, -1, 0, 1};

struct Position {
    int x, y, cnt;
    Position(int a = 0, int b = 0, int c = 0) : x(a), y(b), cnt(c) {}
};

vector<Position> humans, escapePods;

bool okCell(int x, int y, int n) {
    return x >= 0 && x < n && y >= 0 && y < n && grid[x][y] == ROOM;
}

int kindOf(char c) {
    if (c >= '0' && c <= '9') return ROOM;
    if (c == 'Y') return REAC;
    if (c == 'Z') return BAD;
    return -1;
}

int quantityOf(char c) {
    return c - '0';
}

void spreadPoison(int x, int y, int timeLimit, int n) {
    poisonGrid[0][x][y] = 1;

    for (int t = 1; t <= timeLimit; ++t) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (poisonGrid[t - 1][i][j]) {
                    poisonGrid[t][i][j] = 1;

                    for (int d = 0; d < 4; ++d) {
                        int nx = i + mx[d];
                        int ny = j + my[d];

                        if (okCell(nx, ny, n)) {
                            poisonGrid[t][nx][ny] = 1;
                        }
                    }
                }
            }
        }
    }
}

int timeNeeded(const Position &a, const Position &b, int n, int limit) {
    vector<bitset<MAXN>> seen(n);
    queue<pair<int, Position>> q;
    q.push({0, a});
    seen[a.x][a.y] = 1;

    while (!q.empty()) {
        int tim = q.front().first;
        Position cur = q.front().second;
        q.pop();

        if (cur.x == b.x && cur.y == b.y) return tim;
        if (tim == limit) continue;
        if (poisonGrid[tim][cur.x][cur.y]) continue;

        for (int d = 0; d < 4; ++d) {
            Position nxt(cur.x + mx[d], cur.y + my[d], 0);
            if (okCell(nxt.x, nxt.y, n) && !seen[nxt.x][nxt.y] && !poisonGrid[tim][nxt.x][nxt.y]) {
                seen[nxt.x][nxt.y] = 1;
                q.push({tim + 1, nxt});
            }
        }
    }

    return 999;
}

class ArrayMaxFlow {
    int n, edgeCnt;
    vector<int> head;
    vector<int> to, cap, flow, nxt;
    vector<int> parent, parentEdge;

public:
    ArrayMaxFlow(int _n) : n(_n), edgeCnt(0), head(_n, -1), parent(_n), parentEdge(_n) {}

    void addEdge(int u, int v, int c) {
        to.push_back(v);
        cap.push_back(c);
        flow.push_back(0);
        nxt.push_back(head[u]);
        head[u] = edgeCnt++;

        to.push_back(u);
        cap.push_back(0);
        flow.push_back(0);
        nxt.push_back(head[v]);
        head[v] = edgeCnt++;
    }

    bool bfs(int s, int t) {
        fill(parent.begin(), parent.end(), -1);
        fill(parentEdge.begin(), parentEdge.end(), -1);

        queue<int> q;
        q.push(s);
        parent[s] = s;

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = to[e];

                if (parent[v] == -1 && cap[e] - flow[e] > 0) {
                    parent[v] = u;
                    parentEdge[v] = e;

                    if (v == t) return true;
                    q.push(v);
                }
            }
        }

        return false;
    }

    int augment(int s, int t) {
        int pushed = INT_MAX;

        for (int v = t; v != s; v = parent[v]) {
            int e = parentEdge[v];
            pushed = min(pushed, cap[e] - flow[e]);
        }

        for (int v = t; v != s; v = parent[v]) {
            int e = parentEdge[v];
            flow[e] += pushed;
            flow[e ^ 1] -= pushed;
        }

        return pushed;
    }

    long long maxFlow(int s, int t) {
        long long total = 0;

        while (bfs(s, t)) {
            total += augment(s, t);
        }

        return total;
    }
};

int main() {
    int N, T;
    scanf(" %d %d", &N, &T);

    Position badReactor(0, 0, 0);
    char ch;

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &ch);

            int type = kindOf(ch);
            int amount = quantityOf(ch);

            grid[i][j] = type;

            if (type == ROOM && amount > 0) {
                humans.push_back(Position(i, j, amount));
            }

            if (type == BAD) {
                badReactor = Position(i, j, 0);
            }
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &ch);

            int type = kindOf(ch);
            int amount = quantityOf(ch);

            if (type == CAPSULE && amount > 0) {
                escapePods.push_back(Position(i, j, amount));
                capsuleCount[i][j] = amount;
            }
        }
    }

    ArrayMaxFlow flow(MAXN);
    int source = 0;
    int sink = MAXN - 1;

    for (size_t i = 0; i < humans.size(); ++i) {
        flow.addEdge(source, (int)i * 2 + 1, humans[i].cnt);
    }

    for (size_t i = 0; i < escapePods.size(); ++i) {
        flow.addEdge((int)i * 2 + 2, sink, escapePods[i].cnt);
    }

    spreadPoison(badReactor.x, badReactor.y, T, N);

    for (size_t i = 0; i < humans.size(); ++i) {
        for (size_t j = 0; j < escapePods.size(); ++j) {
            int t = timeNeeded(humans[i], escapePods[j], N, T);

            if (t <= T) {
                flow.addEdge((int)i * 2 + 1, (int)j * 2 + 2, 999);
            }
        }
    }

    printf("%lld\n", flow.maxFlow(source, sink));
    return 0;
}
